LEVEL = 1
CFG = {1: "call 555-0100", 2: "ssn 123-45-6789", 3: "card 4111-1111-1111-1111 email a@b.com"}
import re
text = CFG[LEVEL]
pats = {"phone": r"\d{3}-\d{4}", "ssn": r"\d{3}-\d{2}-\d{4}", "card": r"\d{4}(-\d{4}){3}", "email": r"[\w.]+@[\w.]+"}
found = {k: re.findall(p, text) for k, p in pats.items()}
found = {k: v for k, v in found.items() if v}
print("text:", text, "| detected:", found or "none")

